type ProductValidator struct{}

func (v *ProductValidator) ValidateCreateRequest(req *pb.CreateProductRequest) error {
    details := []protoadapt.MessageV1{}

    if req.Name == "" {
        details = append(details, &pb.ErrorDetail{
            Field: "name",
            Message: "Name is required",
        })
    }

    if req.Price < 0 {
        details = append(details, &pb.ErrorDetail{
            Field: "price",
            Message: "Price must be >= 0",
        })
    }

    if len(details) > 0 {
        return custom_error.InvalidRequest(details...)
    }
    return nil
}
```

**Handler**:
```go
func (h *ProductHandler) Create(ctx context.Context, req *pb.CreateProductRequest) (*pb.ProductResponse, error) {
    // 1. Validate TRƯỚC
    if err := h.validator.ValidateCreateRequest(req); err != nil {
        return nil, err  // Return 400 Bad Request
    }

    // 2. Process
    entity := h.mapper.PbToDomain(req)
    result, err := h.usecase.Create(ctx, entity)
    if err != nil {
        return nil, err
    }

    return h.mapper.DomainToPb(result), nil
}
```

**Quy tắc**:
- Validate sớm (fail fast)
- Collect all errors (không return ngay lỗi đầu)
- Field-level errors với message rõ ràng
- Return InvalidRequest với details

Dùng `WithTransaction` pattern để wrap operations:

**Interface**:
```go
type ITransaction interface {
    WithTransaction(ctx context.Context, fn func(ctx context.Context) error) error
}
```

**Implementation**:
```go
func (t *TransactionGorm) WithTransaction(ctx context.Context, fn func(ctx context.Context) error) error {
    return t.DB.Transaction(func(tx *gorm.DB) error {
        // Preserve context values
        profileId := _utils.GetProfileIdWithContext(ctx)
        newCtx := context.WithValue(ctx, "tx", tx)
        newCtx = context.WithValue(newCtx, "profileId", profileId)

        return fn(newCtx)  // Auto rollback nếu error
    })
}
```

**Usecase**:
```go
func (uc *OrderUsecase) CreateOrder(ctx context.Context, order *domain.Order) error {
    return uc.transaction.WithTransaction(ctx, func(ctx context.Context) error {
        // 1. Create order
        if err := uc.orderRepo.Create(ctx, order); err != nil {
            return err  // Rollback
        }

        // 2. Create order items
        for _, item := range order.Items {
            if err := uc.orderItemRepo.Create(ctx, item); err != nil {
                return err  // Rollback ALL
            }
        }

        // 3. Update inventory
        if err := uc.inventoryRepo.Decrease(ctx, order.ProductID); err != nil {
            return err  // Rollback ALL
        }

        return nil  // Commit tất cả
    })
}
```

**Auto behavior**:
- ✅ Return nil → Commit
- ❌ Return error → Rollback ALL
- Context có "tx" key cho nested repos

API list LUÔN trả `data` (array) và `total` (int64):

**Protobuf**:
```protobuf
message ProductListRequest {
  int32 page = 1;
  int32 size = 2;
  string search = 3;
}

message ProductListResponse {
  repeated ProductDTO data = 1;  // Array
  int64 total = 2;               // Total count
}
```

**Handler**:
```go
func (h *ProductHandler) GetList(ctx context.Context, req *pb.ProductListRequest) (*pb.ProductListResponse, error) {
    pagable := _dto.Pagable{
        Page: uint32(req.Page),
        Size: uint32(req.Size),
    }

    // Repo trả về (data, total, error)
    products, total, err := h.usecase.GetList(ctx, &pagable)
    if err != nil {
        return nil, err
    }

    // Map sang protobuf
    pbProducts := make([]*pb.ProductDTO, len(products))
    for i, product := range products {
        pbProducts[i] = h.mapper.DomainToPb(&product)
    }

    // Trả về data + total
    return &pb.ProductListResponse{
        Data:  pbProducts,
        Total: int64(total),
    }, nil
}
```

**Repository**:
```go
func (r *ProductRepo) GetList(ctx context.Context, pagable _dto.IPagable) ([]domain.Product, int64, error) {
    var products []domain.Product
    var total int64

    query := r.DB.Model(&domain.Product{}).Where("deleted_at IS NULL")

    // Count TRƯỚC pagination
    query.Count(&total)

    // Apply pagination
    err := query.
        Offset(pagable.GetOffset()).
        Limit(pagable.GetLimit()).
        Find(&products).Error

    return products, total, err
}
```

**Pagination default**: page=0, size=20, max=100

`CreateInBatches` dùng cho bulk insert nhiều records hiệu quả:

**❌ Slow - Loop create**:
```go
for _, product := range products {
    db.Create(&product)  // 100 products = 100 queries!
}
```

**✅ Fast - Bulk insert**:
```go
db.CreateInBatches(products, 100)  // 1 query với batch size 100
// INSERT INTO products VALUES (1,...), (2,...), (3,...), ...
```

**Repository**:
```go
func (r *ProductRepo) BulkCreate(ctx context.Context, products []domain.Product) error {
    return r.GetDB(ctx).CreateInBatches(products, 100).Error
}
```

**Với transaction**:
```go
func (uc *ProductUsecase) BulkImport(ctx context.Context, dtos []*dto.ProductDTO) error {
    products := make([]domain.Product, len(dtos))
    for i, dto := range dtos {
        products[i] = *uc.mapper.DTOToDomain(dto)
    }

    return uc.transaction.WithTransaction(ctx, func(ctx context.Context) error {
        // Bulk insert
        if err := uc.repo.BulkCreate(ctx, products); err != nil {
            return err  // Rollback tất cả
        }

        // Log history
        for _, product := range products {
            uc.historyClient.Log(ctx, "Product created", product.ID)
        }

        return nil
    })
}
```

**Performance**:
- 1000 records: Loop = 1000 queries (~10s), Batch = 10 queries (~0.5s)
- Batch size recommended: 100-500
- Always wrap in transaction

Client trong `infra/client` để gọi service khác:

**Client definition**:
```go
// @bind: product-service/internal/interface/provider.IUserClient
type UserClient struct {
    client pb_user.UserServiceClient
}

func NewUserClient() *UserClient {
    wrapper := &UserClient{}

    go func() {
        // Connect trong goroutine
        conn, err := grpc.Dial(
            "user-service:50061",
            grpc.WithInsecure(),
            grpc.WithUnaryInterceptor(_middleware.UnaryClientInterceptor),
        )
        if err != nil {
            log.Fatal(err)
        }

        wrapper.client = pb_user.NewUserServiceClient(conn)
    }()

    return wrapper
}

// Wrapper methods
func (c *UserClient) GetUserByID(ctx context.Context, userID uint64) (*pb_user.UserResponse, error) {
    req := &pb_user.GetUserRequest{Id: userID}
    return c.client.GetUser(ctx, req)
}

func (c *UserClient) GetUsersByIDs(ctx context.Context, ids []uint64) ([]*pb_user.UserResponse, error) {
    req := &pb_user.GetUsersRequest{Ids: ids}
    resp, err := c.client.GetUsers(ctx, req)
    if err != nil {
        return nil, err
    }
    return resp.Data, nil
}
```

**Sử dụng trong usecase**:
```go
func (uc *ProductUsecase) GetProductWithUser(ctx context.Context, id uint64) (*dto.ProductDetailDTO, error) {
    // Get product
    product, err := uc.repo.GetByID(ctx, id)
    if err != nil {
        return nil, err
    }

    // Get user info từ user-service
    user, err := uc.userClient.GetUserByID(ctx, product.UserID)
    if err != nil {
        return nil, err
    }

    return &dto.ProductDetailDTO{
        Product:  product,
        UserName: user.Name,
    }, nil
}
```

**Features**:
- Init trong goroutine (non-blocking)
- UnaryInterceptor pass context/JWT
- Wrapper methods clean API
- @bind for DI

Custom error codes theo pattern factory:

**Define error codes**:
```go
package custom_error

import (
    _errors "common/errors"
    "google.golang.org/grpc/codes"
)

var (
    // 4xxx: Client errors
    InvalidRequestCode    codes.Code = 4001
    EntityNotFoundCode    codes.Code = 4002
    DuplicateEntityCode   codes.Code = 4003
    PermissionDeniedCode  codes.Code = 4004

    // 5xxx: Server errors
    InternalErrorCode     codes.Code = 5001
    DatabaseErrorCode     codes.Code = 5002
)

// Factory functions
func InvalidRequest(details ...protoadapt.MessageV1) error {
    return _errors.ThrowError(
        int32(InvalidRequestCode),
        errors.New("invalid request"),
        details...,
    )
}

func EntityNotFound(entityType string) error {
    return _errors.ThrowError(
        int32(EntityNotFoundCode),
        errors.New(fmt.Sprintf("%s not found", entityType)),
    )
}

func DuplicateEntity(entityType string) error {
    return _errors.ThrowError(
        int32(DuplicateEntityCode),
        errors.New(fmt.Sprintf("%s already exists", entityType)),
    )
}

func PermissionDenied(message string) error {
    return _errors.ThrowError(
        int32(PermissionDeniedCode),
        errors.New(message),
    )
}
```

**Sử dụng**:
```go
func (uc *ProductUsecase) Create(ctx context.Context, product *domain.Product) error {
    // Validation
    if product.Name == "" {
        return custom_error.InvalidRequest()
    }

    // Check duplicate
    existing, _ := uc.repo.FindByName(ctx, product.Name)
    if existing != nil {
        return custom_error.DuplicateEntity("product")
    }

    // Permission
    if !uc.HasPermission(ctx, "create") {
        return custom_error.PermissionDenied("cannot create product")
    }

    return uc.repo.Create(ctx, product)
}
```

**Middleware auto convert**: 4001 → HTTP 400, 4002 → HTTP 404, 5001 → HTTP 500

